using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;

[Serializable] public class NemoWalkRoom {public Vector2 center,radius;public string purpose;}
[Serializable] public class NemoWalkRibbon {public Vector2[] points;public float width;public string purpose;}
[Serializable] public class NemoWalkContour {public Vector2[] points;}
// Intended ground access. Parcel packing has no role in physical blocking.
public class NemoWalkRegion : MonoBehaviour
{
    public const float Step=1f/16f;public const int Width=2304,Height=1728;
    public NemoWalkRoom[] Rooms,ForestIslands;public NemoWalkRibbon[] Ribbons;public NemoWalkContour[] Contours;public Rect[] WaterTerrain;
    public int AllowedCells;public string SavedGroundMask;public GameObject Overlay;[NonSerialized]bool[] cells;
    public bool Contains(Vector2 p){if(cells==null)Raster();int x=Mathf.FloorToInt(p.x/Step),y=Mathf.FloorToInt(p.y/Step);return x>=0&&x<Width&&y>=0&&y<Height&&cells[x+y*Width];}
    void Paint(bool[] target,Rect box,Func<Vector2,bool> inside,bool value,bool[] protect=null){int x0=Mathf.Max(0,Mathf.FloorToInt(box.xMin/Step)),x1=Mathf.Min(Width-1,Mathf.CeilToInt(box.xMax/Step));int y0=Mathf.Max(0,Mathf.FloorToInt(box.yMin/Step)),y1=Mathf.Min(Height-1,Mathf.CeilToInt(box.yMax/Step));for(int y=y0;y<=y1;y++)for(int x=x0;x<=x1;x++){int k=x+y*Width;if(protect!=null&&protect[k])continue;var p=new Vector2((x+.5f)*Step,(y+.5f)*Step);if(inside(p))target[k]=value;}}
    void Ellipse(bool[] target,NemoWalkRoom room,bool value,bool[] protect=null){var r=room.radius;Paint(target,new Rect(room.center-r,r*2),p=>{var d=p-room.center;return d.x*d.x/(r.x*r.x)+d.y*d.y/(r.y*r.y)<1;},value,protect);}
    void Ribbon(bool[] target,NemoWalkRibbon route,float width){for(int i=1;i<route.points.Length;i++){var a=route.points[i-1];var b=route.points[i];var min=Vector2.Min(a,b)-Vector2.one*width;var max=Vector2.Max(a,b)+Vector2.one*width;Paint(target,new Rect(min,max-min),p=>NemoMap.Distance(p,a,b)<width,true);}}
    void Raster(){if(!string.IsNullOrEmpty(SavedGroundMask)){var packed=Convert.FromBase64String(SavedGroundMask);cells=new bool[Width*Height];for(int k=0;k<cells.Length;k++)cells[k]=(packed[k>>3]&(1<<(k&7)))!=0;return;}throw new Exception("Ground mask missing; build from completed block design first");}
    void FromFixedDesign(NemoMap map){cells=Enumerable.Repeat(true,Width*Height).ToArray();var textures=new Dictionary<Texture2D,Color32[]>();
        foreach(var render in map.Design.Forest.SelectMany(s=>s.visuals).Where(r=>r.sprite!=null&&r.color.a>=.85f)){
            var sprite=render.sprite;var source=sprite.texture;if(!textures.TryGetValue(source,out var pixels)){
                if(source.isReadable)pixels=source.GetPixels32();else{var target=RenderTexture.GetTemporary(source.width,source.height,0,RenderTextureFormat.ARGB32);var prior=RenderTexture.active;Graphics.Blit(source,target);RenderTexture.active=target;var copy=new Texture2D(source.width,source.height,TextureFormat.RGBA32,false);copy.ReadPixels(new Rect(0,0,source.width,source.height),0,0);copy.Apply();pixels=copy.GetPixels32();UnityEngine.Object.DestroyImmediate(copy);RenderTexture.active=prior;RenderTexture.ReleaseTemporary(target);}textures[source]=pixels;}
            var origin=(Vector2)render.transform.position;var pivot=sprite.pivot;var rect=sprite.rect;float ppu=sprite.pixelsPerUnit;bool flipX=render.flipX,flipY=render.flipY;int textureWidth=source.width;var bounds=render.bounds;int x0=Mathf.Max(0,Mathf.FloorToInt(bounds.min.x/Step)),x1=Mathf.Min(Width-1,Mathf.CeilToInt(bounds.max.x/Step)),y0=Mathf.Max(0,Mathf.FloorToInt(bounds.min.y/Step)),y1=Mathf.Min(Height-1,Mathf.CeilToInt(bounds.max.y/Step));
            for(int y=y0;y<=y1;y++)for(int x=x0;x<=x1;x++){int at=x+y*Width;if(!cells[at])continue;var local=new Vector2((x+.5f)*Step-origin.x,(y+.5f)*Step-origin.y);int px=Mathf.FloorToInt(local.x*ppu+pivot.x),py=Mathf.FloorToInt(local.y*ppu+pivot.y);if(flipX)px=(int)rect.width-1-px;if(flipY)py=(int)rect.height-1-py;if(px<0||py<0||px>=rect.width||py>=rect.height)continue;int index=((int)rect.y+py)*textureWidth+(int)rect.x+px;if(pixels[index].a>=160)cells[at]=false;}
        }
        // The block's already-rendered soil and working courts own their ground. Tree canopy overhang does not erase a designed street.
        foreach(var filter in map.Design.Ground){var vertices=filter.sharedMesh.vertices.Select(v=>(Vector2)filter.transform.TransformPoint(v)).ToArray();var triangles=filter.sharedMesh.triangles;for(int k=0;k<triangles.Length;k+=3){var a=vertices[triangles[k]];var b=vertices[triangles[k+1]];var c=vertices[triangles[k+2]];var min=Vector2.Min(a,Vector2.Min(b,c));var max=Vector2.Max(a,Vector2.Max(b,c));float Cross(Vector2 u,Vector2 v)=>u.x*v.y-u.y*v.x;Paint(cells,new Rect(min,max-min),p=>{float ab=Cross(b-a,p-a),bc=Cross(c-b,p-b),ca=Cross(a-c,p-c);return (ab>=0&&bc>=0&&ca>=0)||(ab<=0&&bc<=0&&ca<=0);},true);}}
        foreach(var water in WaterTerrain)Paint(cells,water,p=>water.Contains(p),false);KeepConnectedGround();AllowedCells=cells.Count(c=>c);var packed=new byte[(cells.Length+7)/8];for(int k=0;k<cells.Length;k++)if(cells[k])packed[k>>3]|=(byte)(1<<(k&7));SavedGroundMask=Convert.ToBase64String(packed);
    }
    void KeepConnectedGround(){var seen=new bool[cells.Length];var queue=new Queue<int>();int start=Mathf.FloorToInt(Rooms[0].center.x/Step)+Mathf.FloorToInt(Rooms[0].center.y/Step)*Width;if(!cells[start])throw new Exception("Central hub outside walking region");seen[start]=true;queue.Enqueue(start);while(queue.Count>0){int k=queue.Dequeue(),x=k%Width,y=k/Width;foreach(int n in new[]{x>0?k-1:-1,x<Width-1?k+1:-1,y>0?k-Width:-1,y<Height-1?k+Width:-1})if(n>=0&&cells[n]&&!seen[n]){seen[n]=true;queue.Enqueue(n);}}cells=seen;}
    void Outline(){var edges=new Dictionary<Vector2Int,List<Vector2Int>>();void Add(int x,int y,int xx,int yy){var a=new Vector2Int(x,y);if(!edges.TryGetValue(a,out var list))edges[a]=list=new List<Vector2Int>();list.Add(new Vector2Int(xx,yy));}bool On(int x,int y)=>x>=0&&y>=0&&x<Width&&y<Height&&cells[x+y*Width];
        for(int y=0;y<Height;y++)for(int x=0;x<Width;x++)if(On(x,y)){if(!On(x,y-1))Add(x,y,x+1,y);if(!On(x+1,y))Add(x+1,y,x+1,y+1);if(!On(x,y+1))Add(x+1,y+1,x,y+1);if(!On(x-1,y))Add(x,y+1,x,y);}
        var loops=new List<NemoWalkContour>();var starts=edges.Keys.ToArray();int startIndex=0;while(edges.Count>0){while(!edges.ContainsKey(starts[startIndex]))startIndex++;var start=starts[startIndex];var at=start;var chain=new List<Vector2Int>();Vector2Int prior=Vector2Int.right;int guard=0;do{chain.Add(at);var outgoing=edges[at];var next=outgoing.OrderByDescending(p=>{var d=p-at;return Mathf.Atan2(prior.x*d.y-prior.y*d.x,prior.x*d.x+prior.y*d.y);}).First();outgoing.Remove(next);if(outgoing.Count==0)edges.Remove(at);prior=next-at;at=next;if(++guard>100000)throw new Exception("Walk contour did not close");}while(at!=start);
            if(chain.Count<3)continue;var reduced=new List<Vector2>();for(int i=0;i<chain.Count;i++){var a=chain[(i+chain.Count-1)%chain.Count];var b=chain[i];var c=chain[(i+1)%chain.Count];if(b-a!=c-b)reduced.Add((Vector2)b*Step);}if(reduced.Count<3)continue;
            // Keep the actual pixel/terrain contour. Long-edge rounding must never cut across designed ground.
            reduced.Add(reduced[0]);loops.Add(new NemoWalkContour{points=reduced.ToArray()});}
        Contours=loops.ToArray();
    }
    public static NemoWalkRegion Build(NemoMap map,Transform parent){if(map.Design==null)throw new Exception("Block visual design must be fixed before walking/collision");var region=new GameObject("Walking area derived from fixed native forest and terrain").AddComponent<NemoWalkRegion>();region.transform.SetParent(parent);region.Rooms=new[]{new NemoWalkRoom{center=map.Plan.parcels[0].hub,purpose="central flood-fill origin"}};region.Ribbons=new NemoWalkRibbon[0];region.ForestIslands=new NemoWalkRoom[0];region.WaterTerrain=map.RiverNetwork==null?new Rect[0]:map.RiverNetwork.WaterBodies.Select(c=>new Rect((Vector2)c.bounds.min,(Vector2)c.bounds.size)).ToArray();region.FromFixedDesign(map);region.Outline();region.Overlay=new GameObject("Walking contour debug | green | H");region.Overlay.transform.SetParent(parent);var material=new Material(Shader.Find("Sprites/Default"));map.Transient.Add(material);foreach(var c in region.Contours){var g=new GameObject("Design-derived walking contour");g.transform.SetParent(region.Overlay.transform);var line=g.AddComponent<LineRenderer>();line.sharedMaterial=material;line.positionCount=c.points.Length;line.SetPositions(c.points.Select(p=>new Vector3(p.x,p.y,-1f)).ToArray());line.startColor=line.endColor=new Color(.2f,1,.35f,1);line.startWidth=line.endWidth=.10f;line.sortingOrder=31000;}region.Overlay.SetActive(false);return region;}
}
